/* ============================================================
   HDEC — Colors & Type Foundations
   Holocaust Documentation & Education Center, Inc.
   ============================================================ */

:root {
  /* ---------- Primary palette ---------- */
  --hdec-primary-blue: #1a5fb4;     /* buttons, links, icon fills, accents */
  --hdec-dark-navy:    #1a2744;     /* hero overlays, dark sections, testimony */
  --hdec-deep-navy:    #0f1620;     /* footer, darkest UI surfaces */
  --hdec-light-blue:   #7ab3f0;     /* eyebrow text on dark, subtle accents */

  /* ---------- Neutrals ---------- */
  --hdec-white:        #ffffff;
  --hdec-surface:      #f5f7fa;     /* alternating section bg, card surfaces */
  --hdec-border:       #dde3ed;     /* card borders, dividers */
  --hdec-body:         #1a1a1a;     /* primary body copy */
  --hdec-muted:        #555555;     /* secondary copy, captions */
  --hdec-hint:         #888888;     /* labels, dates, metadata */

  /* ---------- Volunteer (single-purpose) ---------- */
  --hdec-volunteer:    #2d7d46;     /* volunteer CTA only */
  --hdec-volunteer-dk: #235e35;     /* volunteer hover */

  /* ---------- State variants ---------- */
  --hdec-primary-blue-hover: #154a8e;
  --hdec-primary-blue-press: #103a72;
  --hdec-focus-ring:        #7ab3f0;

  /* ---------- Semantic surface tokens ---------- */
  --bg-canvas:       var(--hdec-white);
  --bg-alt:          var(--hdec-surface);
  --bg-dark:         var(--hdec-dark-navy);
  --bg-darker:       var(--hdec-deep-navy);
  --fg-primary:      var(--hdec-body);
  --fg-secondary:    var(--hdec-muted);
  --fg-tertiary:     var(--hdec-hint);
  --fg-on-dark:      var(--hdec-white);
  --fg-eyebrow-dark: var(--hdec-light-blue);
  --accent:          var(--hdec-primary-blue);
  --border:          var(--hdec-border);

  /* ---------- Typography (Arial only — no exceptions) ---------- */
  --font-stack: Arial, Helvetica, sans-serif;
  --weight-regular: 400;
  --weight-bold:    700;

  /* Type scale (px) — from brand guide */
  --fs-page-title:    40px;   /* 36–42 */
  --fs-section-title: 26px;   /* 24–28 */
  --fs-subsection:    20px;   /* 18–22 */
  --fs-body:          16px;   /* 14–16 */
  --fs-body-sm:       14px;
  --fs-label:         11px;   /* 10–12, ALL CAPS */

  /* Line heights */
  --lh-tight:  1.2;
  --lh-snug:   1.3;
  --lh-body:   1.7;

  /* Letter spacing */
  --ls-label:    0.08em;   /* labels / nav */
  --ls-nav:      0.03em;
  --ls-normal:   0;

  /* ---------- Spacing scale ---------- */
  --space-1:  4px;
  --space-2:  8px;
  --space-3:  12px;
  --space-4:  16px;
  --space-5:  20px;
  --space-6:  24px;
  --space-8:  32px;
  --space-10: 40px;
  --space-12: 48px;   /* section vertical padding */
  --space-16: 64px;
  --space-20: 80px;
  --space-24: 96px;

  /* ---------- Radii ---------- */
  --radius-button: 4px;
  --radius-card:   6px;
  --radius-pill:   999px;

  /* ---------- Borders ---------- */
  --border-hairline: 1px solid var(--border);

  /* ---------- Shadows (functional only) ---------- */
  --shadow-none: none;
  --focus-ring: 0 0 0 3px rgba(122, 179, 240, 0.55);

  /* ---------- Donate pulse keyframe color ---------- */
  --pulse-ring: rgba(26, 95, 180, 0.55);

  /* ---------- Layout ---------- */
  --container-max: 1280px;
  --container-pad: 24px;
  --section-pad-y: 64px;
}

/* ============================================================
   Base element styles
   ============================================================ */

html, body {
  font-family: var(--font-stack);
  font-size:   var(--fs-body);
  line-height: var(--lh-body);
  color:       var(--fg-primary);
  background:  var(--bg-canvas);
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-stack);
  font-weight: var(--weight-bold);
  line-height: var(--lh-tight);
  color: var(--fg-primary);
  margin: 0 0 var(--space-4);
  text-wrap: pretty;
}

h1 { font-size: var(--fs-page-title); }
h2 { font-size: var(--fs-section-title); }
h3 { font-size: var(--fs-subsection); }
h4 { font-size: 18px; }
h5 { font-size: 16px; }
h6 { font-size: 14px; }

p {
  margin: 0 0 var(--space-4);
  line-height: var(--lh-body);
  color: var(--fg-primary);
}

a {
  color: var(--accent);
  text-decoration: none;
  font-weight: var(--weight-bold);
}
a:hover { color: var(--hdec-primary-blue-hover); text-decoration: underline; }

small, .text-muted { color: var(--fg-secondary); font-size: var(--fs-body-sm); }
.text-hint { color: var(--fg-tertiary); }

/* Eyebrow / label */
.eyebrow,
.label {
  font-size: var(--fs-label);
  font-weight: var(--weight-bold);
  text-transform: uppercase;
  letter-spacing: var(--ls-label);
  color: var(--accent);
}
.eyebrow--on-dark { color: var(--fg-eyebrow-dark); }

/* Nav-style text */
.nav-item {
  font-weight: var(--weight-bold);
  letter-spacing: var(--ls-nav);
  color: var(--accent);
}

/* Text link with arrow */
.text-link {
  color: var(--accent);
  font-weight: var(--weight-bold);
  letter-spacing: var(--ls-nav);
}
.text-link::after { content: " \2192"; }

/* ============================================================
   Donate-button pulse keyframe (used in Components)
   ============================================================ */
@keyframes hdec-pulse {
  0%   { box-shadow: 0 0 0 0   var(--pulse-ring); }
  70%  { box-shadow: 0 0 0 14px rgba(26, 95, 180, 0); }
  100% { box-shadow: 0 0 0 0   rgba(26, 95, 180, 0); }
}

/* Subtle entrance for the page itself on first paint */
@keyframes hdec-fade-up {
  from { opacity: 0; transform: translateY(12px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* Honor reduced-motion */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
  }
}

/* eslint-disable */

const { useState } = React;

// --- shared icons (Lucide-style) -----------------------------------------
const Icon = ({ name, size = 18, stroke = 2 }) => {
  const common = { width: size, height: size, viewBox: "0 0 24 24", fill: "none", stroke: "currentColor", strokeWidth: stroke, strokeLinecap: "round", strokeLinejoin: "round" };
  const paths = {
    search:   <><circle cx="11" cy="11" r="7" /><path d="m20 20-3.5-3.5" /></>,
    chevron:  <path d="m6 9 6 6 6-6" />,
    arrow:    <><path d="M5 12h14" /><path d="M13 5l7 7-7 7" /></>,
    facebook: <path d="M22 12a10 10 0 1 0-11.6 9.9V15h-2.5v-3h2.5V9.7c0-2.5 1.5-3.9 3.8-3.9 1.1 0 2.2.2 2.2.2v2.5h-1.3c-1.2 0-1.6.8-1.6 1.6V12h2.7l-.4 3h-2.3v6.9A10 10 0 0 0 22 12z" />,
    instagram:<><rect x="3" y="3" width="18" height="18" rx="5" /><circle cx="12" cy="12" r="4" /><circle cx="17.5" cy="6.5" r="0.6" fill="currentColor" /></>,
    youtube:  <path d="M22 8.2s-.2-1.4-.8-2c-.7-.8-1.6-.8-2-.9C16 5 12 5 12 5s-4 0-7.2.3c-.4.1-1.3.1-2 .9-.6.6-.8 2-.8 2S1.8 9.8 1.8 11.5v1.6c0 1.7.2 3.3.2 3.3s.2 1.4.8 2c.7.8 1.7.8 2.2.9 1.6.2 6.8.3 6.8.3s4 0 7.2-.3c.4-.1 1.3-.1 2-.9.6-.6.8-2 .8-2s.2-1.6.2-3.3v-1.6c0-1.7-.2-3.3-.2-3.3zM10 14.5V8.8l5.3 2.9z" />,
    linkedin: <><rect x="3" y="3" width="18" height="18" rx="2"/><path d="M8 10v7M8 7v.01M12 17v-4a2 2 0 0 1 4 0v4M12 10v7"/></>,
    mail:     <><rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 6 9-6"/></>,
    phone:    <path d="M22 16.9v3a2 2 0 0 1-2.2 2 19.8 19.8 0 0 1-8.6-3.1 19.5 19.5 0 0 1-6-6 19.8 19.8 0 0 1-3.1-8.7A2 2 0 0 1 4.1 2h3a2 2 0 0 1 2 1.7 12.8 12.8 0 0 0 .7 2.8 2 2 0 0 1-.5 2.1L8 9.8a16 16 0 0 0 6 6l1.2-1.2a2 2 0 0 1 2.1-.5 12.8 12.8 0 0 0 2.8.7A2 2 0 0 1 22 16.9z"/>,
    pin:      <><path d="M20 10c0 7-8 12-8 12s-8-5-8-12a8 8 0 1 1 16 0z"/><circle cx="12" cy="10" r="3"/></>,
  };
  return <svg {...common} aria-hidden="true">{paths[name]}</svg>;
};

// --- primitives ---------------------------------------------------------
const Container = ({ children, style }) => (
  <div style={{ maxWidth: 1280, margin: "0 auto", padding: "0 24px", ...style }}>{children}</div>
);

const Eyebrow = ({ children, onDark = false, style }) => (
  <div style={{
    fontSize: 11, fontWeight: 700, letterSpacing: "0.1em", textTransform: "uppercase",
    color: onDark ? "#7ab3f0" : "#1a5fb4",
    marginBottom: 12, ...style,
  }}>{children}</div>
);

const buttonStyles = {
  base: {
    fontFamily: "Arial, sans-serif", fontWeight: 700, fontSize: 14,
    padding: "12px 22px", borderRadius: 4, border: 0, cursor: "pointer",
    letterSpacing: "0.03em", lineHeight: 1.2, transition: "background 150ms ease",
  },
  primary:   { background: "#1a5fb4", color: "#fff" },
  ghost:     { background: "transparent", color: "#fff", border: "1.5px solid #fff", padding: "10.5px 20.5px" },
  ghostBlue: { background: "#fff", color: "#1a5fb4", border: "1.5px solid #1a5fb4", padding: "10.5px 20.5px" },
  volunteer: { background: "#2d7d46", color: "#fff" },
  donate:    { background: "#1a5fb4", color: "#fff", padding: "13px 26px", fontSize: 15, animation: "hdec-pulse 2s infinite" },
};
const Button = ({ variant = "primary", children, ...rest }) => (
  <button {...rest} style={{ ...buttonStyles.base, ...buttonStyles[variant], ...(rest.style || {}) }}>{children}</button>
);

const TextLink = ({ children, onDark = false, ...rest }) => (
  <a {...rest} style={{
    color: onDark ? "#7ab3f0" : "#1a5fb4", fontWeight: 700, letterSpacing: "0.02em",
    textDecoration: "none", fontSize: 14,
  }}>{children} <span aria-hidden="true">→</span></a>
);

// Photo placeholder — used everywhere imagery is required from the client
const PhotoPlaceholder = ({ ratio = "16/9", caption, dark = true, children, style }) => (
  <div style={{
    aspectRatio: ratio, width: "100%", background: dark ? "#1a2744" : "#f5f7fa",
    border: dark ? "0" : "1px solid #dde3ed", color: dark ? "#7ab3f0" : "#888",
    display: "flex", alignItems: "center", justifyContent: "center",
    position: "relative", overflow: "hidden", ...style,
  }}>
    {/* subtle texture marker so placeholders are obvious */}
    <div style={{ position: "absolute", inset: 0, backgroundImage: "repeating-linear-gradient(45deg, transparent 0 22px, rgba(255,255,255,0.03) 22px 23px)" }} />
    {children || (
      <div style={{ position: "relative", textAlign: "center", padding: 16 }}>
        <div style={{ fontSize: 10, fontWeight: 700, letterSpacing: "0.15em", textTransform: "uppercase", marginBottom: 6 }}>
          Photo placeholder
        </div>
        <div style={{ fontSize: 13, lineHeight: 1.5, maxWidth: 320, margin: "0 auto", opacity: 0.85 }}>
          {caption}
        </div>
      </div>
    )}
  </div>
);

Object.assign(window, { Icon, Container, Eyebrow, Button, TextLink, PhotoPlaceholder });

