3	const { useState: useRevState, useEffect: useRevEffect, useRef: useRevRef } = React;
4	
5	// Reveal-on-scroll wrapper.
6	// usage: <Reveal delay={120}><Card/></Reveal>
7	const Reveal = ({ children, delay = 0, y = 16, as: Tag = "div", style, ...rest }) => {
8	  const ref = useRevRef(null);
9	  const [shown, setShown] = useRevState(false);
10	
11	  useRevEffect(() => {
12	    const el = ref.current;
13	    if (!el) return;
14	    if (typeof IntersectionObserver === "undefined") { setShown(true); return; }
15	    const io = new IntersectionObserver((entries) => {
16	      entries.forEach((e) => {
17	        if (e.isIntersecting) { setShown(true); io.disconnect(); }
18	      });
19	    }, { threshold: 0.12, rootMargin: "0px 0px -40px 0px" });
20	    io.observe(el);
21	    return () => io.disconnect();
22	  }, []);
23	
24	  return (
25	    <Tag
26	      ref={ref}
27	      style={{
28	        transition: "opacity 700ms ease, transform 700ms cubic-bezier(.2,.7,.2,1)",
29	        transitionDelay: delay + "ms",
30	        opacity: shown ? 1 : 0,
31	        transform: shown ? "translateY(0)" : `translateY(${y}px)`,
32	        willChange: "opacity, transform",
33	        ...style,
34	      }}
35	      {...rest}
36	    >{children}</Tag>
37	  );
38	};
39	
40	// Count-up number, animates when first visible
41	const CountUp = ({ value, duration = 1200, startDelay = 0, suffix = "", style }) => {
42	  const ref = useRevRef(null);
43	  const [n, setN] = useRevState(0);
44	  const started = useRevRef(false);
45	
46	  useRevEffect(() => {
47	    const el = ref.current;
48	    if (!el) return;
49	    const target = parseFloat(String(value).replace(/[^0-9.]/g, "")) || 0;
50	    const begin = () => {
51	      const t0 = performance.now();
52	      const tick = (t) => {
53	        const p = Math.min(1, (t - t0) / duration);
54	        const eased = 1 - Math.pow(1 - p, 3);
55	        setN(target * eased);
56	        if (p < 1) requestAnimationFrame(tick);
57	        else setN(target);
58	      };
59	      requestAnimationFrame(tick);
60	    };
61	    const io = new IntersectionObserver((entries) => {
62	      entries.forEach((e) => {
63	        if (e.isIntersecting && !started.current) {
64	          started.current = true;
65	          if (startDelay > 0) setTimeout(begin, startDelay);
66	          else begin();
67	        }
68	      });
69	    }, { threshold: 0.4 });
70	    io.observe(el);
71	    return () => io.disconnect();
72	  }, [value, duration, startDelay]);
73	
74	  // format with same separators as input string
75	  const formatted = (() => {
76	    const target = parseFloat(String(value).replace(/[^0-9.]/g, "")) || 0;
77	    if (target >= 1000) return Math.round(n).toLocaleString();
78	    return Math.round(n).toString();
79	  })();
