/* eslint-disable */

const { useState: useRevState, useEffect: useRevEffect, useRef: useRevRef } = React;

// Reveal-on-scroll wrapper.
// usage: <Reveal delay={120}><Card/></Reveal>
const Reveal = ({ children, delay = 0, y = 16, as: Tag = "div", style, ...rest }) => {
  const ref = useRevRef(null);
  const [shown, setShown] = useRevState(false);

  useRevEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (typeof IntersectionObserver === "undefined") { setShown(true); return; }
    const io = new IntersectionObserver((entries) => {
      entries.forEach((e) => {
        if (e.isIntersecting) { setShown(true); io.disconnect(); }
      });
    }, { threshold: 0.12, rootMargin: "0px 0px -40px 0px" });
    io.observe(el);
    return () => io.disconnect();
  }, []);

  return (
    <Tag
      ref={ref}
      style={{
        transition: "opacity 700ms ease, transform 700ms cubic-bezier(.2,.7,.2,1)",
        transitionDelay: delay + "ms",
        opacity: shown ? 1 : 0,
        transform: shown ? "translateY(0)" : `translateY(${y}px)`,
        willChange: "opacity, transform",
        ...style,
      }}
      {...rest}
    >{children}</Tag>
  );
};

// Count-up number, animates when first visible
const CountUp = ({ value, duration = 1200, startDelay = 0, suffix = "", style }) => {
  const ref = useRevRef(null);
  const [n, setN] = useRevState(0);
  const started = useRevRef(false);

  useRevEffect(() => {
    const el = ref.current;
    if (!el) return;
    const target = parseFloat(String(value).replace(/[^0-9.]/g, "")) || 0;
    const begin = () => {
      const t0 = performance.now();
      const tick = (t) => {
        const p = Math.min(1, (t - t0) / duration);
        const eased = 1 - Math.pow(1 - p, 3);
        setN(target * eased);
        if (p < 1) requestAnimationFrame(tick);
        else setN(target);
      };
      requestAnimationFrame(tick);
    };
    const io = new IntersectionObserver((entries) => {
      entries.forEach((e) => {
        if (e.isIntersecting && !started.current) {
          started.current = true;
          if (startDelay > 0) setTimeout(begin, startDelay);
          else begin();
        }
      });
    }, { threshold: 0.4 });
    io.observe(el);
    return () => io.disconnect();
  }, [value, duration, startDelay]);

  // format with same separators as input string
  const formatted = (() => {
    const target = parseFloat(String(value).replace(/[^0-9.]/g, "")) || 0;
    if (target >= 1000) return Math.round(n).toLocaleString();
    return Math.round(n).toString();
  })();

  return <span ref={ref} style={style}>{formatted}{suffix}</span>;
};

Object.assign(window, { Reveal, CountUp });

/* eslint-disable */

const { useState, useEffect } = React;

const Header = () => {
  const [open, setOpen] = useState(false);

  useEffect(() => {
    const onKey = (e) => { if (e.key === "Escape") setOpen(false); };
    window.addEventListener("keydown", onKey);
    document.body.style.overflow = open ? "hidden" : "";
    return () => { window.removeEventListener("keydown", onKey); document.body.style.overflow = ""; };
  }, [open]);

  return (
    <header style={{ background: "#fff", position: "sticky", top: 0, zIndex: 50 }}>
      {/* Tagline ribbon */}
      <div style={{ background: "#1a2744", color: "#7ab3f0" }}>
        <Container style={{ padding: "7px 24px", display: "flex", justifyContent: "center", alignItems: "center" }}>
          <span style={{
            fontSize: 11, fontWeight: 700, letterSpacing: "0.18em", textTransform: "uppercase",
            color: "#7ab3f0",
          }}>
            The first South Florida Holocaust museum
          </span>
        </Container>
      </div>

      {/* Top bar */}
      <div style={{ borderBottom: "1px solid #dde3ed" }}>
        <Container style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "8px 24px" }}>
          <nav style={{ display: "flex", gap: 18, fontSize: 12 }}>
            <a href="#" style={topLinkStyle}>Plan your visit</a>
            <span style={{ color: "#dde3ed" }}>·</span>
            <a href="#" style={topLinkStyle}>Upcoming events</a>
            <span style={{ color: "#dde3ed" }}>·</span>
            <a href="#" style={topLinkStyle}>Share your testimony</a>
          </nav>
          <button style={{ background: "transparent", border: 0, color: "#1a5fb4", padding: 4, cursor: "pointer", display: "flex", alignItems: "center" }} aria-label="Search">
            <Icon name="search" size={18} stroke={2.2} />
          </button>
        </Container>
      </div>

      {/* Main header */}
      <div style={{ borderBottom: "1px solid #dde3ed" }}>
        <Container style={{ display: "flex", alignItems: "center", gap: 32, justifyContent: "space-between", padding: "16px 24px" }}>
          <a href="#" style={{ display: "block", lineHeight: 0 }}>
            <img src="../../assets/hdec-logo.png" alt="Holocaust Documentation and Education Center, Inc." style={{ height: 48, width: "auto" }} />
          </a>

          <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
            <Button variant="donate">Donate</Button>
            <button
              onClick={() => setOpen((o) => !o)}
              aria-label="Open menu"
              aria-expanded={open}
              style={{
                display: "inline-flex", alignItems: "center", gap: 10,
                background: open ? "#1a5fb4" : "#fff",
                color: open ? "#fff" : "#1a5fb4",
                border: "1.5px solid #1a5fb4",
                borderRadius: 4, padding: "11px 16px",
                fontFamily: "Arial, sans-serif", fontWeight: 700, fontSize: 14,
                letterSpacing: "0.06em", textTransform: "uppercase", cursor: "pointer",
                transition: "background 150ms ease, color 150ms ease",
              }}
            >
              <Burger open={open} />
              <span>{open ? "Close" : "Menu"}</span>
            </button>
          </div>
        </Container>
      </div>

      <MegaMenu open={open} onClose={() => setOpen(false)} />
    </header>
  );
};

const Burger = ({ open }) => (
  <span style={{ position: "relative", width: 16, height: 12, display: "inline-block" }} aria-hidden="true">
    <span style={{ ...barStyle, top: 0, transform: open ? "translateY(5px) rotate(45deg)" : "none" }} />
    <span style={{ ...barStyle, top: 5, opacity: open ? 0 : 1 }} />
    <span style={{ ...barStyle, top: 10, transform: open ? "translateY(-5px) rotate(-45deg)" : "none" }} />
  </span>
);
const barStyle = {
  position: "absolute", left: 0, width: "100%", height: 2,
  background: "currentColor", borderRadius: 1,
  transition: "transform 180ms ease, opacity 120ms ease",
};

const MegaMenu = ({ open, onClose }) => {
  if (!open) return null;
  const cols = [
    {
      heading: "About",
      links: [
        { l: "About us", sub: "Mission, history, leadership" },
        { l: "Life & Legacy", sub: "Survivor stories" },
        { l: "Positions", sub: "Open roles at HDEC" },
        { l: "In the news", sub: "Press & announcements" },
      ],
    },
    {
      heading: "Documentation & Education",
      links: [
        { l: "Documentation", sub: "Oral history archives" },
        { l: "Education", sub: "K–12 curriculum & workshops" },
        { l: "Online programming", sub: "Virtual tours & livestreams" },
      ],
    },
    {
      heading: "Visit",
      links: [
        { l: "Museum", sub: "Galleries & permanent installations" },
        { l: "Exhibitions", sub: "Current and upcoming" },
        { l: "Plan your visit", sub: "Hours, directions, tickets" },
      ],
    },
  ];

  return (
    <>
      <div onClick={onClose} style={{
        position: "fixed", inset: 0, background: "rgba(15, 22, 32, 0.45)",
        zIndex: 60, animation: "hdec-fade 160ms ease-out",
      }} />
      <div style={{
        position: "absolute", left: 0, right: 0, top: "100%",
        background: "#fff", borderBottom: "1px solid #dde3ed",
        zIndex: 70, animation: "hdec-slide 200ms ease-out",
      }}>
        <Container style={{ padding: "40px 24px 48px" }}>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr) 280px", gap: 32 }}>
            {cols.map((col) => (
              <nav key={col.heading} aria-label={col.heading}>
                <div style={{
                  fontSize: 11, fontWeight: 700, letterSpacing: "0.12em", textTransform: "uppercase",
                  color: "#1a5fb4", paddingBottom: 12, marginBottom: 14, borderBottom: "1px solid #dde3ed",
                }}>{col.heading}</div>
                <ul style={{ listStyle: "none", margin: 0, padding: 0, display: "flex", flexDirection: "column", gap: 14 }}>
                  {col.links.map((it) => (
                    <li key={it.l}>
                      <a href="#" onClick={onClose} style={{ textDecoration: "none", display: "block" }}>
                        <div style={{ color: "#1a5fb4", fontWeight: 700, fontSize: 17, lineHeight: 1.3, letterSpacing: "0.01em" }}>{it.l}</div>
                        <div style={{ color: "#555", fontSize: 13, lineHeight: 1.4, marginTop: 2 }}>{it.sub}</div>
                      </a>
                    </li>
                  ))}
                </ul>
              </nav>
            ))}

            {/* Contact card */}
            <aside style={{ background: "#1a2744", color: "#fff", borderRadius: 6, padding: 22 }}>
              <div style={{ fontSize: 11, fontWeight: 700, letterSpacing: "0.12em", textTransform: "uppercase", color: "#7ab3f0", marginBottom: 14 }}>Contact</div>
              <ul style={{ listStyle: "none", margin: 0, padding: 0, display: "flex", flexDirection: "column", gap: 12, fontSize: 14 }}>
                <li style={{ display: "flex", gap: 10, alignItems: "center" }}>
                  <span style={{ color: "#7ab3f0" }}><Icon name="phone" size={16} /></span>
                  <a href="tel:9549295690" style={{ color: "#fff", textDecoration: "none", fontWeight: 700 }}>(954) 929-5690</a>
                </li>
                <li style={{ display: "flex", gap: 10, alignItems: "center" }}>
                  <span style={{ color: "#7ab3f0" }}><Icon name="mail" size={16} /></span>
                  <a href="mailto:info@hdec.org" style={{ color: "#fff", textDecoration: "none", fontWeight: 700 }}>info@hdec.org</a>
                </li>
                <li style={{ display: "flex", gap: 10, alignItems: "flex-start" }}>
                  <span style={{ color: "#7ab3f0", marginTop: 2 }}><Icon name="pin" size={16} /></span>
                  <span style={{ color: "rgba(255,255,255,0.85)", lineHeight: 1.5 }}>303 N Federal Hwy<br />Dania Beach, FL 33004</span>
                </li>
              </ul>
              <div style={{ height: 1, background: "rgba(122,179,240,0.25)", margin: "18px 0" }} />
              <a href="#" onClick={onClose} style={{ color: "#7ab3f0", fontWeight: 700, fontSize: 13, letterSpacing: "0.04em", textDecoration: "none" }}>
                Full contact info <span aria-hidden="true">→</span>
              </a>
            </aside>
          </div>
        </Container>
      </div>
      <style>{`
        @keyframes hdec-fade { from { opacity: 0; } to { opacity: 1; } }
        @keyframes hdec-slide { from { opacity: 0; transform: translateY(-8px); } to { opacity: 1; transform: translateY(0); } }
      `}</style>
    </>
  );
};

const topLinkStyle = {
  color: "#1a5fb4", fontWeight: 700, letterSpacing: "0.04em", textDecoration: "none",
};

window.Header = Header;

/* eslint-disable */

const CalloutStrip = () => {
  const items = [
    { title: "Interactive Learning Center" },
    { title: "Holocaust Railcar & Sherman Tank" },
    { title: "Education Mandated by Law" },
  ];
  return (
    <section style={{ background: "#f5f7fa", borderBottom: "1px solid #dde3ed" }}>
      <Container style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)" }}>
        {items.map((it, i) => (
          <a key={i} href="#" className="hdec-callout" style={{
            padding: "20px 24px", textAlign: "center",
            borderLeft: i === 0 ? 0 : "1px solid #dde3ed",
            textDecoration: "none", display: "block",
            transition: "background 180ms ease",
          }}>
            <div style={{ fontSize: 15, fontWeight: 700, color: "#1a2744", letterSpacing: "0.02em", marginBottom: 6 }}>{it.title}</div>
            <span style={{ color: "#1a5fb4", fontWeight: 700, fontSize: 12, letterSpacing: "0.06em", textTransform: "uppercase" }}>
              Learn more <span aria-hidden="true" className="hdec-callout-arrow">→</span>
            </span>
          </a>
        ))}
      </Container>
      <style>{`
        .hdec-callout:hover { background: #fff; }
        .hdec-callout-arrow { display: inline-block; transition: transform 200ms ease; }
        .hdec-callout:hover .hdec-callout-arrow { transform: translateX(4px); }
      `}</style>
    </section>
  );
};
window.CalloutStrip = CalloutStrip;

