const { useState: useHeroState, useEffect: useHeroEffect, useRef: useHeroRef } = React;

const HERO_SLIDES = [
  {
    eyebrow: "Education mandated by law",
    title: "Florida law requires every student to learn this history.",
    body: "HDEC partners with school districts statewide to deliver curriculum that meets the Florida Holocaust Education Mandate — for every grade, every teacher, every classroom.",
    cta: "Explore K-12 education",
    img: "https://hdec.org/wp-content/uploads/2019/07/Mandate-signing-8-x-10.jpg",
    alt: "Signing of the Florida Holocaust Education Mandate",
  },
  {
    eyebrow: "A national first",
    title: "The country's first Interactive Learning Center for Holocaust education.",
    body: "Visitors step into immersive galleries that pair survivor testimony with primary documents, artifacts, and hands-on learning — the first installation of its kind in the United States.",
    cta: "Plan your visit",
    img: "https://hdec.org/wp-content/uploads/2017/07/education1.jpg",
    alt: "Students inside the HDEC Interactive Learning Center",
  },
  {
    eyebrow: "Railcar & Sherman Tank",
    title: "Walk through the railcar. Stand beside the tank that liberated.",
    body: "Two of the most powerful artifacts in our permanent collection — an authentic European railcar and a WWII Sherman Tank — anchor the museum experience and our survivors' testimonies.",
    cta: "Hear the testimonials",
    img: "https://hdec.org/wp-content/uploads/2017/07/hdec-tank.jpg",
    alt: "WWII Sherman Tank installation at HDEC",
  },
];

const Hero = () => {
  const [i, setI] = useHeroState(0);
  const [paused, setPaused] = useHeroState(false);
  const total = HERO_SLIDES.length;
  const goTo = (n) => setI(((n % total) + total) % total);

  useHeroEffect(() => {
    if (paused) return;
    const id = setInterval(() => setI((c) => (c + 1) % total), 7000);
    return () => clearInterval(id);
  }, [paused, total]);

  return (
    <section
      onMouseEnter={() => setPaused(true)}
      onMouseLeave={() => setPaused(false)}
      style={{ position: "relative", color: "#fff", overflow: "hidden", background: "#1a2744" }}
      aria-roledescription="carousel"
      aria-label="HDEC highlights"
    >
      {/* Slides */}
      {HERO_SLIDES.map((s, idx) => (
        <div
          key={idx}
          aria-hidden={idx !== i}
          style={{
            position: idx === 0 ? "relative" : "absolute",
            inset: idx === 0 ? "auto" : 0,
            top: 0, left: 0, right: 0,
            opacity: idx === i ? 1 : 0,
            transition: "opacity 600ms ease",
            pointerEvents: idx === i ? "auto" : "none",
            minHeight: 560,
            display: "flex", alignItems: "center",
          }}
        >
          <img
            src={s.img}
            alt={s.alt}
            style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover" }}
          />
          <div style={{ position: "absolute", inset: 0, background: "rgba(15, 22, 32, 0.72)" }} />
          <Container style={{ position: "relative", padding: "96px 24px" }}>
            <div style={{ maxWidth: 720 }}>
              <Eyebrow onDark>{s.eyebrow}</Eyebrow>
              <h1 style={{ fontSize: 48, fontWeight: 700, lineHeight: 1.15, margin: "0 0 18px", color: "#fff", letterSpacing: "-0.005em" }}>
                {s.title}
              </h1>
              <p style={{ fontSize: 18, lineHeight: 1.6, color: "rgba(255,255,255,0.88)", maxWidth: 600, margin: "0 0 28px" }}>
                {s.body}
              </p>
              <div style={{ display: "flex", gap: 12, flexWrap: "wrap" }}>
                <Button variant="primary">{s.cta}</Button>
                <Button variant="ghost">Learn more</Button>
              </div>
            </div>
          </Container>
        </div>
      ))}

      {/* Controls */}
      <div style={{
        position: "absolute", left: 0, right: 0, bottom: 0,
        padding: "18px 24px", display: "flex", alignItems: "center", justifyContent: "space-between",
        background: "linear-gradient(to top, rgba(15,22,32,0.55), rgba(15,22,32,0))",
      }}>
        <Container style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: 0 }}>
          {/* Tab indicators */}
          <div style={{ display: "flex", gap: 28, flex: 1, maxWidth: 720 }}>
            {HERO_SLIDES.map((s, idx) => (
              <button
                key={idx}
                onClick={() => goTo(idx)}
                style={{
                  flex: 1, textAlign: "left", background: "transparent", border: 0, color: "#fff",
                  cursor: "pointer", padding: "10px 0 0", borderTop: idx === i ? "3px solid #fff" : "3px solid rgba(255,255,255,0.25)",
                  fontFamily: "Arial, sans-serif", transition: "border-color 200ms ease",
                }}
                aria-current={idx === i ? "true" : undefined}
                aria-label={"Show slide " + (idx + 1)}
              >
                <div style={{
                  fontSize: 10, fontWeight: 700, letterSpacing: "0.14em", textTransform: "uppercase",
                  color: idx === i ? "#7ab3f0" : "rgba(122,179,240,0.7)", marginBottom: 4,
                }}>
                  {String(idx + 1).padStart(2, "0")}
                </div>
                <div style={{ fontSize: 13, fontWeight: 700, lineHeight: 1.35, color: idx === i ? "#fff" : "rgba(255,255,255,0.7)" }}>
                  {s.eyebrow}
                </div>
              </button>
            ))}
          </div>

          {/* Prev / Next */}
          <div style={{ display: "flex", gap: 10, marginLeft: 24 }}>
            <button
              onClick={() => goTo(i - 1)}
              aria-label="Previous slide"
              style={arrowBtnStyle}
            >
              <svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="m15 18-6-6 6-6"/></svg>
            </button>
            <button
              onClick={() => goTo(i + 1)}
              aria-label="Next slide"
              style={arrowBtnStyle}
            >
              <svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="m9 18 6-6-6-6"/></svg>
            </button>
          </div>
        </Container>
      </div>
    </section>
  );
};

const arrowBtnStyle = {
  width: 40, height: 40, borderRadius: 4,
  background: "rgba(255,255,255,0.12)", color: "#fff",
  border: "1px solid rgba(255,255,255,0.35)",
  cursor: "pointer", display: "inline-flex", alignItems: "center", justifyContent: "center",
};

window.Hero = Hero;

/* eslint-disable */

const OurStoryCollage = () => {
  const cards = [
    {
      eyebrow: "How we started",
      title: "Founded by survivors, in 1980.",
      body: "Survivors and educators came together in South Florida to ensure that what they lived through would never be forgotten — or repeated.",
      cta: "Read our history",
      img: "https://hdec.org/wp-content/uploads/2017/07/hdec-documentation-rita.png",
      alt: "HDEC archivist documenting a Survivor's testimony",
    },
    {
      eyebrow: "Who we are",
      title: "South Florida's first Holocaust museum.",
      body: "A nondenominational nonprofit dedicated to documentation, oral history preservation, K-12 education, and community engagement.",
      cta: "About HDEC",
      filled: true,
    },
    {
      eyebrow: "Why we do it",
      title: "So testimony outlives the witnesses.",
      body: "Every voice we record, every student we teach, every program we host extends the chain of memory by another link.",
      cta: "Our mission",
      img: "https://hdec.org/wp-content/uploads/2017/07/hdec-large-group.jpg",
      alt: "HDEC community gathering",
    },
  ];

  return (
    <section style={{ background: "#fff", padding: "72px 0" }}>
      <Container>
        <Reveal>
          <div style={{ marginBottom: 40, maxWidth: 720 }}>
            <Eyebrow>Our story</Eyebrow>
            <h2 style={{ fontSize: 32, fontWeight: 700, lineHeight: 1.2, margin: 0 }}>
              For more than four decades, HDEC has preserved the testimonies of those who lived through the Holocaust — and shared them with the next generation.
            </h2>
          </div>
        </Reveal>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 20 }}>
          {cards.map((c, i) => (
            <Reveal key={i} delay={i * 120}>
              <StoryCard c={c} />
            </Reveal>
          ))}
        </div>
      </Container>
    </section>
  );
};

const StoryCard = ({ c }) => {
  const [hover, setHover] = React.useState(false);
  return (
    <article
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      style={{
        background: c.filled ? "#1a5fb4" : "#fff",
        border: "1px solid " + (c.filled ? "#1a5fb4" : (hover ? "#1a5fb4" : "#dde3ed")),
        borderRadius: 6, overflow: "hidden", display: "flex", flexDirection: "column",
        color: c.filled ? "#fff" : "#1a1a1a",
        transition: "border-color 200ms ease, transform 300ms ease",
        transform: hover ? "translateY(-2px)" : "none",
        height: "100%",
      }}
    >
      {!c.filled && (
        <div style={{ aspectRatio: "4 / 3", width: "100%", overflow: "hidden", background: "#1a2744" }}>
          <img
            src={c.img}
            alt={c.alt}
            style={{
              width: "100%", height: "100%", objectFit: "cover", display: "block",
              transition: "transform 600ms cubic-bezier(.2,.7,.2,1)",
              transform: hover ? "scale(1.06)" : "scale(1)",
            }}
          />
        </div>
      )}
      {c.filled && (
        <div style={{ padding: "32px 24px 0", color: "#7ab3f0", fontSize: 11, fontWeight: 700, letterSpacing: "0.12em", textTransform: "uppercase" }}>
          Our story
        </div>
      )}
      <div style={{ padding: c.filled ? "8px 24px 28px" : "20px 22px 24px", display: "flex", flexDirection: "column", gap: 12 }}>
        {!c.filled && <Eyebrow style={{ marginBottom: 0 }}>{c.eyebrow}</Eyebrow>}
        <h3 style={{ fontSize: 20, fontWeight: 700, lineHeight: 1.25, margin: 0, color: c.filled ? "#fff" : "#1a1a1a" }}>{c.title}</h3>
        <p style={{ fontSize: 14, lineHeight: 1.65, margin: 0, color: c.filled ? "rgba(255,255,255,0.85)" : "#555" }}>{c.body}</p>
        <a href="#" style={{
          color: c.filled ? "#fff" : "#1a5fb4", fontWeight: 700, fontSize: 13, letterSpacing: "0.04em", textDecoration: "none", marginTop: 4,
          display: "inline-flex", alignItems: "center", gap: 6,
        }}>
          {c.cta}
          <span aria-hidden="true" style={{ display: "inline-block", transition: "transform 200ms ease", transform: hover ? "translateX(4px)" : "none" }}>→</span>
        </a>
      </div>
    </article>
  );
};

window.OurStoryCollage = OurStoryCollage;

/* eslint-disable */

const ProgramsTiles = () => {
  const tiles = [
    {
      eyebrow: "What's next",
      title: "Upcoming programming",
      body: "Speaker series, gallery talks, commemorations, and educator workshops at our Dania Beach campus.",
      cta: "See the calendar",
      variant: "primary",
    },
    {
      eyebrow: "From anywhere",
      title: "Online programming",
      body: "Stream survivor testimony, virtual tours, and live programs from your classroom or home.",
      cta: "Watch online",
      variant: "primary",
    },
    {
      eyebrow: "Get involved",
      title: "Volunteers needed",
      body: "Docents, archivists, education assistants, and event support — give your time to a mission that matters.",
      cta: "Volunteer with HDEC",
      variant: "volunteer",
    },
  ];
  return (
    <section style={{ background: "#f5f7fa", padding: "72px 0" }}>
      <Container>
        <Reveal>
          <div style={{ marginBottom: 32, display: "flex", alignItems: "flex-end", justifyContent: "space-between", gap: 24, flexWrap: "wrap" }}>
            <div style={{ maxWidth: 640 }}>
              <Eyebrow>Programs &amp; involvement</Eyebrow>
              <h2 style={{ fontSize: 32, fontWeight: 700, lineHeight: 1.2, margin: 0 }}>Step into the work.</h2>
            </div>
            <a href="#" style={{ color: "#1a5fb4", fontWeight: 700, fontSize: 14, letterSpacing: "0.03em", textDecoration: "none" }}>
              All programs <span aria-hidden="true">→</span>
            </a>
          </div>
        </Reveal>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 20 }}>
          {tiles.map((t, i) => (
            <Reveal key={i} delay={i * 120}>
              <ProgramTile t={t} />
            </Reveal>
          ))}
        </div>
      </Container>
    </section>
  );
};

const ProgramTile = ({ t }) => {
  const [hover, setHover] = React.useState(false);
  return (
    <article
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      style={{
        background: "#fff",
        border: "1px solid " + (hover ? "#1a5fb4" : "#dde3ed"),
        borderRadius: 6, padding: 24, display: "flex", flexDirection: "column", gap: 12,
        transition: "border-color 200ms ease, transform 300ms ease",
        transform: hover ? "translateY(-2px)" : "none",
        height: "100%",
      }}
    >
      <Eyebrow style={{ marginBottom: 0 }}>{t.eyebrow}</Eyebrow>
      <h3 style={{ fontSize: 22, fontWeight: 700, lineHeight: 1.25, margin: 0 }}>{t.title}</h3>
      <p style={{ fontSize: 14, lineHeight: 1.65, color: "#555", margin: 0, flex: 1 }}>{t.body}</p>
      <div style={{ marginTop: 6 }}>
        <Button variant={t.variant}>{t.cta}</Button>
      </div>
    </article>
  );
};

window.ProgramsTiles = ProgramsTiles;

