  <script type="text/babel">
/* eslint-disable */
const { useState: useTBState, useRef: useTBRef } = React;

const TESTIMONY_QUOTES = [
  {
    pos: { top: "14%", left: "6%" },
    width: 280,
    quote: "I survived because someone, somewhere, decided to remember.",
    name: "Eva H.",
    detail: "Auschwitz survivor · Recorded 1994",
  },
  {
    pos: { bottom: "12%", left: "5%" },
    width: 300,
    quote: "My father never spoke of it. The day he sat down with HDEC was the day our family began to heal.",
    name: "Daniel R.",
    detail: "Son of a Survivor · Recorded 2018",
  },
  {
    pos: { top: "22%", right: "5%" },
    width: 290,
    quote: "I walked through the gates of Dachau on April 29, 1945. I have not stopped walking back since.",
    name: "Lt. Col. James M.",
    detail: "Liberator, U.S. 42nd Infantry · Recorded 2003",
  },
];

const HoverQuote = ({ data }) => {
  const [progress, setProgress] = useTBState(0);
  const dirRef = useTBRef(0);
  const rafRef = useTBRef(null);
  const lastT = useTBRef(0);

  const tick = (t) => {
    if (!lastT.current) lastT.current = t;
    const dt = Math.min(0.05, (t - lastT.current) / 1000);
    lastT.current = t;
    setProgress((p) => {
      const rate = dirRef.current === 1 ? 0.55 : -0.7;
      const np = Math.max(0, Math.min(1, p + rate * dt));
      const stillGoing = (dirRef.current === 1 && np < 1) || (dirRef.current === -1 && np > 0);
      if (stillGoing) { rafRef.current = requestAnimationFrame(tick); }
      else { rafRef.current = null; }
      return np;
    });
  };

  const ensureRunning = () => {
    if (!rafRef.current) { lastT.current = 0; rafRef.current = requestAnimationFrame(tick); }
  };
  const start = () => { dirRef.current = 1; ensureRunning(); };
  const stop  = () => { dirRef.current = -1; ensureRunning(); };

  const opacity = progress;
  const blur = (1 - progress) * 6;
  const lift = (1 - progress) * 6;

  return (
    <div
      onMouseEnter={start} onMouseLeave={stop} onFocus={start} onBlur={stop}
      tabIndex={0}
      aria-label={`Reveal testimony from ${data.name}`}
      style={{ position: "absolute", ...data.pos, width: data.width, padding: 16, cursor: "default", outline: "none", pointerEvents: "auto" }}
    >
      <div style={{ display: "flex", gap: 5, marginBottom: 8, opacity: 1 - progress * 0.85, transition: "opacity 200ms linear" }}>
        {[0, 1, 2].map((i) => (
          <span key={i} style={{ width: 5, height: 5, borderRadius: "50%", background: "#7ab3f0" }} />
        ))}
      </div>
      <div style={{ height: 1, background: "rgba(122,179,240,0.28)", opacity: 1 - progress * 0.85, transition: "opacity 200ms linear" }} />
      <div style={{ marginTop: 14, opacity, filter: `blur(${blur}px)`, transform: `translateY(${lift}px)`, willChange: "opacity, filter, transform" }}>
        <div style={{ fontSize: 16, fontWeight: 400, lineHeight: 1.55, color: "rgba(255,255,255,0.92)", letterSpacing: "0.005em" }}>
          &ldquo;{data.quote}&rdquo;
        </div>
        <div style={{ marginTop: 10, fontSize: 11, fontWeight: 700, letterSpacing: "0.12em", textTransform: "uppercase", color: "#7ab3f0" }}>
          {data.name}
        </div>
        <div style={{ marginTop: 2, fontSize: 12, color: "rgba(255,255,255,0.55)" }}>{data.detail}</div>
      </div>
    </div>
  );
};

const TestimonyBand = () => {
  const stats = [
    { n: "40",     suffix: "+", l: "Years preserving memory" },
    { n: "10000",  suffix: "+", l: "Testimonies recorded" },
    { n: "500000", suffix: "+", l: "Students reached" },
    { n: "1000",   suffix: "+", l: "Programs delivered" },
  ];
  return (
    <section style={{ background: "#1a2744", color: "#fff", padding: "88px 0", position: "relative", overflow: "hidden" }}>
      <div style={{ position: "absolute", inset: 0, pointerEvents: "none" }}>
        {TESTIMONY_QUOTES.map((q, i) => (
          <HoverQuote key={i} data={q} />
        ))}
      </div>
      <Container style={{ position: "relative", zIndex: 2, pointerEvents: "none" }}>
        <Reveal>
          <div style={{ maxWidth: 720, margin: "0 auto", textAlign: "center", pointerEvents: "auto" }}>
            <Eyebrow onDark>Share your testimony</Eyebrow>
            <blockquote style={{
              margin: "0 auto 24px", fontSize: 28, fontWeight: 700, lineHeight: 1.35, letterSpacing: "-0.005em",
              color: "#fff", maxWidth: 660,
            }}>
              "For the dead and the living, we must bear witness."
              <div style={{ marginTop: 14, fontSize: 12, fontWeight: 700, letterSpacing: "0.12em", textTransform: "uppercase", color: "#7ab3f0" }}>
                — Elie Wiesel
              </div>
            </blockquote>
            <p style={{ fontSize: 16, lineHeight: 1.7, color: "rgba(255,255,255,0.82)", margin: "0 auto 28px", maxWidth: 580 }}>
              If you are a Survivor, Liberator, or Witness — or a family member who carries a story forward — HDEC will preserve your testimony for generations to come.
            </p>
            <Button variant="primary">Share your testimony</Button>
            <div style={{ marginTop: 22, fontSize: 11, fontWeight: 700, letterSpacing: "0.14em", textTransform: "uppercase", color: "rgba(122,179,240,0.6)" }}>
              Hover the dots · listen to the voices around you
            </div>
          </div>
        </Reveal>
        <div style={{
          marginTop: 64, display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 24,
          borderTop: "1px solid rgba(122,179,240,0.25)", paddingTop: 40, pointerEvents: "auto",
        }}>
          {stats.map((s, i) => (
            <Reveal key={i} delay={i * 100}>
              <div style={{ textAlign: "center" }}>
                <div style={{ fontSize: 44, fontWeight: 700, lineHeight: 1, color: "#fff", marginBottom: 8, letterSpacing: "-0.01em" }}>
                  <CountUp value={s.n} suffix={s.suffix} duration={1200} startDelay={i * 1200} />
                </div>
                <div style={{ fontSize: 11, fontWeight: 700, letterSpacing: "0.12em", textTransform: "uppercase", color: "#7ab3f0" }}>{s.l}</div>
              </div>
            </Reveal>
          ))}
        </div>
      </Container>
    </section>
  );
};
window.TestimonyBand = TestimonyBand;
  </script>

