  <script type="text/babel">
const { useState: useRevState, useEffect: useRevEffect, useRef: useRevRef } = React;

const Reveal = ({ children, delay = 0, y = 16, as: Tag = "div", style, ...rest }) => {
  const ref = useRevRef(null);
  const [shown, setShown] = useRevState(false);
  useRevEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (typeof IntersectionObserver === "undefined") { setShown(true); return; }
    const io = new IntersectionObserver((entries) => {
      entries.forEach((e) => { if (e.isIntersecting) { setShown(true); io.disconnect(); } });
    }, { threshold: 0.12, rootMargin: "0px 0px -40px 0px" });
    io.observe(el);
    return () => io.disconnect();
  }, []);
  return (
    <Tag ref={ref} style={{ transition: "opacity 700ms ease, transform 700ms cubic-bezier(.2,.7,.2,1)", transitionDelay: delay + "ms", opacity: shown ? 1 : 0, transform: shown ? "translateY(0)" : `translateY(${y}px)`, willChange: "opacity, transform", ...style }} {...rest}>{children}</Tag>
  );
};

const CountUp = ({ value, duration = 1200, startDelay = 0, suffix = "" }) => {
  const ref = useRevRef(null);
  const [n, setN] = useRevState(0);
  const started = useRevRef(false);
  useRevEffect(() => {
    const el = ref.current;
    if (!el) return;
    const target = parseFloat(String(value).replace(/[^0-9.]/g, "")) || 0;
    const begin = () => {
      const t0 = performance.now();
      const tick = (t) => {
        const p = Math.min(1, (t - t0) / duration);
        setN(target * (1 - Math.pow(1 - p, 3)));
        if (p < 1) requestAnimationFrame(tick); else setN(target);
      };
      requestAnimationFrame(tick);
    };
    const io = new IntersectionObserver((entries) => {
      entries.forEach((e) => { if (e.isIntersecting && !started.current) { started.current = true; startDelay > 0 ? setTimeout(begin, startDelay) : begin(); } });
    }, { threshold: 0.4 });
    io.observe(el);
    return () => io.disconnect();
  }, [value, duration, startDelay]);
  const formatted = (() => { const t = parseFloat(String(value).replace(/[^0-9.]/g, "")) || 0; return t >= 1000 ? Math.round(n).toLocaleString() : Math.round(n).toString(); })();
  return <span ref={ref}>{formatted}{suffix}</span>;
};

Object.assign(window, { Reveal, CountUp });
  </script>

