// WaterQuote: completely invisible until hovered. No dots, no hairlines.
// Hovering adds ripple bursts at the zone and fades the quote in.
const WaterQuote = ({ data, onRipple }) => {
  const [progress, setProgress] = useTBState(0);
  const dirRef = useTBRef(0);
  const rafRef = useTBRef(null);
  const lastT = useTBRef(0);
  const elRef = useTBRef(null);

  const tick = (t) => {
    if (!lastT.current) lastT.current = t;
    const dt = Math.min(0.05, (t - lastT.current) / 1000);
    lastT.current = t;
    setProgress(p => {
      const rate = dirRef.current === 1 ? 0.5 : -0.65;
      const np = Math.max(0, Math.min(1, p + rate * dt));
      const still = (dirRef.current === 1 && np < 1) || (dirRef.current === -1 && np > 0);
      if (still) rafRef.current = requestAnimationFrame(tick);
      else rafRef.current = null;
      return np;
    });
  };
  const run = () => { if (!rafRef.current) { lastT.current = 0; rafRef.current = requestAnimationFrame(tick); } };

  const handleEnter = (e) => {
    dirRef.current = 1; run();
    // Burst of ripples from zone center
    if (elRef.current) {
      const r = elRef.current.getBoundingClientRect();
      const cx = r.left + r.width / 2;
      const cy = r.top + r.height / 2;
      onRipple(cx, cy, true);
      setTimeout(() => onRipple(cx + 20, cy - 15, false), 180);
      setTimeout(() => onRipple(cx - 15, cy + 20, false), 340);
    }
  };
  const handleLeave = () => { dirRef.current = -1; run(); };

  return (
    <div ref={elRef}
      onMouseEnter={handleEnter} onMouseLeave={handleLeave}
      onFocus={handleEnter} onBlur={handleLeave}
      tabIndex={0} aria-label={`Testimony from ${data.name}`}
      style={{ position:"absolute", ...data.pos, width:data.width, padding:16, pointerEvents:"auto", cursor:"default", outline:"none" }}>
      <div style={{
        opacity: progress,
        filter: `blur(${(1 - progress) * 10}px)`,
        transform: `translateY(${(1 - progress) * 10}px)`,
        willChange: "opacity, filter, transform",
      }}>
        <div style={{ fontSize:16, lineHeight:1.6, color:"rgba(255,255,255,0.92)", fontWeight:400 }}>&#x201C;{data.quote}&#x201D;</div>
        <div style={{ marginTop:12, fontSize:11, fontWeight:700, letterSpacing:"0.12em", textTransform:"uppercase", color:"#7ab3f0" }}>{data.name}</div>
        <div style={{ marginTop:3, fontSize:12, color:"rgba(255,255,255,0.5)" }}>{data.detail}</div>
      </div>
    </div>
  );
};

const TestimonyBand = () => {
  const canvasRef = useTBRef(null);
  const ripplesRef = useTBRef([]);
  const animRef = useTBRef(null);
  const lastCursorRipple = useTBRef(0);

  // Canvas water ripple loop
  useTBEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');

    const resize = () => {
      canvas.width = canvas.offsetWidth;
      canvas.height = canvas.offsetHeight;
    };
    resize();

    let lastAmbient = 0;
    const loop = (t) => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Sparse ambient ripples across the whole surface
      if (t - lastAmbient > 2200) {
        ripplesRef.current.push({
          x: Math.random() * canvas.width,
          y: Math.random() * canvas.height,
          maxR: 80 + Math.random() * 70,
          born: t, ambient: true,
        });
        lastAmbient = t;
      }

      ripplesRef.current = ripplesRef.current.filter(rip => {
        const progress = Math.min(1, (t - rip.born) / (rip.ambient ? 2400 : 1200));
        if (progress >= 1) return false;
        const eased = 1 - Math.pow(1 - progress, 2.5);
        const radius = eased * rip.maxR;
        const alpha = (1 - progress) * (rip.ambient ? 0.055 : (rip.big ? 0.22 : 0.15));

        // Outer ring
        ctx.beginPath();
        ctx.arc(rip.x, rip.y, radius, 0, Math.PI * 2);
        ctx.strokeStyle = `rgba(122,179,240,${alpha})`;
        ctx.lineWidth = rip.ambient ? 1 : 1.5;
        ctx.stroke();

        // Inner concentric ring
        if (radius > 20) {
          ctx.beginPath();
          ctx.arc(rip.x, rip.y, radius * 0.58, 0, Math.PI * 2);
          ctx.strokeStyle = `rgba(122,179,240,${alpha * 0.45})`;
          ctx.lineWidth = 1;
          ctx.stroke();
        }

        // Tertiary ring for big bursts
        if (rip.big && radius > 45) {
          ctx.beginPath();
          ctx.arc(rip.x, rip.y, radius * 0.28, 0, Math.PI * 2);
          ctx.strokeStyle = `rgba(122,179,240,${alpha * 0.3})`;
          ctx.lineWidth = 1;
          ctx.stroke();
        }

        return true;
      });

      animRef.current = requestAnimationFrame(loop);
    };
    animRef.current = requestAnimationFrame(loop);

    const ro = new ResizeObserver(resize);
    ro.observe(canvas);
    return () => { cancelAnimationFrame(animRef.current); ro.disconnect(); };
  }, []);

  // Add a ripple at a viewport coordinate
  const addRipple = (clientX, clientY, big = false) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    ripplesRef.current.push({
      x: clientX - rect.left,
      y: clientY - rect.top,
      maxR: big ? 130 : 65,
      born: performance.now(),
      ambient: false,
      big,
    });
  };

  // Cursor movement creates gentle ripples
  const handleMouseMove = (e) => {
    const now = performance.now();
    if (now - lastCursorRipple.current < 130) return;
    lastCursorRipple.current = now;
    addRipple(e.clientX, e.clientY, false);
  };

  const stats = [
    { n:"40",     suffix:"+", l:"Years preserving memory" },
    { n:"10000",  suffix:"+", l:"Testimonies recorded" },
    { n:"500000", suffix:"+", l:"Students reached" },
    { n:"1000",   suffix:"+", l:"Programs delivered" },
  ];

  return (
    <section onMouseMove={handleMouseMove}
      style={{ background:"#1a2744",color:"#fff",padding:"88px 0",position:"relative",overflow:"hidden",cursor:"default" }}>

      {/* Water canvas — sits behind everything */}
      <canvas ref={canvasRef}
        style={{ position:"absolute",inset:0,width:"100%",height:"100%",pointerEvents:"none",zIndex:1 }} />

      {/* Hidden quote zones — completely invisible, pointer-events on */}
      <div style={{ position:"absolute",inset:0,pointerEvents:"none",zIndex:2 }}>
        {TESTIMONY_QUOTES.map((q,i) => <WaterQuote key={i} data={q} onRipple={addRipple} />)}
      </div>

      {/* Main content */}
      <Container style={{ position:"relative",zIndex:3,pointerEvents:"none" }}>
        <Reveal>
          <div style={{ maxWidth:720,margin:"0 auto",textAlign:"center",pointerEvents:"auto" }}>
            <Eyebrow onDark>Share your testimony</Eyebrow>
            <blockquote style={{ margin:"0 auto 24px",fontSize:28,fontWeight:700,lineHeight:1.35,color:"#fff",maxWidth:660 }}>
              &#x201C;For the dead and the living, we must bear witness.&#x201D;
              <div style={{ marginTop:14,fontSize:12,fontWeight:700,letterSpacing:"0.12em",textTransform:"uppercase",color:"#7ab3f0" }}>
                &#x2014; Elie Wiesel
              </div>
            </blockquote>
            <p style={{ fontSize:16,lineHeight:1.7,color:"rgba(255,255,255,0.82)",margin:"0 auto 28px",maxWidth:"58ch" }}>
              If you are a Survivor, Liberator, or Witness — or a family member who carries a story forward — HDEC will preserve your testimony for generations to come.
            </p>
            <Button variant="primary">Share your testimony</Button>
            <div style={{ marginTop:22,fontSize:11,fontWeight:700,letterSpacing:"0.14em",textTransform:"uppercase",color:"rgba(122,179,240,0.45)" }}>
              Move through this space &middot; voices will find you
            </div>
          </div>
