  <div ref={elRef} style={{ position:"absolute", ...data.pos, width:220, pointerEvents:"none" }}>
    <div style={{ display:"flex", flexDirection:"column", alignItems:"center",
      opacity: Math.max(0, 1 - reveal * 1.4), transition:"opacity 400ms ease" }}>
      <PortraitCircle data={data} size={110} opacity={0.55} />
      <div style={{ marginTop:8, fontSize:10, fontWeight:700, letterSpacing:"0.14em",
        textTransform:"uppercase", color:"rgba(122,179,240,0.45)", textAlign:"center" }}>{data.name}</div>
    </div>
    <div style={{ position:"absolute", top:0, left:0, right:0,
      opacity: reveal, filter:`blur(${(1-reveal)*10}px)`, transform:`translateY(${(1-reveal)*10}px)`,
      transition:"opacity 400ms ease, filter 400ms ease, transform 400ms ease", willChange:"opacity,filter,transform" }}>
      <div style={{ fontSize:14, lineHeight:1.65, color:"rgba(255,255,255,0.92)", fontStyle:"italic" }}>"{data.quote}"</div>
      <div style={{ marginTop:10, fontSize:10, fontWeight:700, letterSpacing:"0.14em", textTransform:"uppercase", color:"#7ab3f0" }}>{data.name}</div>
      <div style={{ marginTop:3, fontSize:11, color:"rgba(255,255,255,0.5)" }}>{data.detail}</div>
    </div>
  </div>
));

// Tablet/small-desktop: static card in 3-col grid
const FaceCard = ({ data }) => (
  <div style={{ display:"flex", flexDirection:"column", alignItems:"center", gap:12, padding:"16px 8px" }}>
    <PortraitCircle data={data} size={90} opacity={0.7} />
    <div style={{ textAlign:"center" }}>
      <div style={{ fontSize:10, fontWeight:700, letterSpacing:"0.12em", textTransform:"uppercase",
        color:"#7ab3f0", marginBottom:8 }}>{data.name}</div>
      <p style={{ fontSize:13, lineHeight:1.6, color:"rgba(255,255,255,0.80)", margin:0, fontStyle:"italic" }}>"{data.quote}"</p>
      <div style={{ marginTop:6, fontSize:10, color:"rgba(255,255,255,0.4)" }}>{data.detail}</div>
    </div>
  </div>
);

// Mobile: auto-rotating carousel
const FaceCarousel = () => {
  const [idx, setIdx] = useTBState(0);
  const [paused, setPaused] = useTBState(false);
  const total = TESTIMONY_QUOTES.length;

  useTBEffect(() => {
    if (paused) return;
    const id = setInterval(() => setIdx(c => (c + 1) % total), 4500);
    return () => clearInterval(id);
  }, [paused, total]);

  const go = (n) => { setIdx(((n % total) + total) % total); setPaused(true); };
  const q = TESTIMONY_QUOTES[idx];

  return (
    <div onTouchStart={() => setPaused(true)} style={{ textAlign:"center", padding:"0 16px" }}>
      <div style={{ display:"flex", justifyContent:"center", marginBottom:16 }}>
        <PortraitCircle data={q} size={120} opacity={0.75} />
      </div>
      <div style={{ fontSize:10, fontWeight:700, letterSpacing:"0.14em", textTransform:"uppercase",
        color:"#7ab3f0", marginBottom:10 }}>{q.name}</div>
      <p style={{ fontSize:15, lineHeight:1.65, color:"rgba(255,255,255,0.88)", margin:"0 0 8px", fontStyle:"italic",
        maxWidth:340, marginLeft:"auto", marginRight:"auto" }}>"{q.quote}"</p>
      <div style={{ fontSize:11, color:"rgba(255,255,255,0.45)", marginBottom:20 }}>{q.detail}</div>
      {/* Dot nav */}
      <div style={{ display:"flex", justifyContent:"center", gap:8 }}>
        {TESTIMONY_QUOTES.map((_, i) => (
          <button key={i} onClick={() => go(i)} aria-label={`Go to testimony ${i+1}`}
            style={{ width: i===idx ? 20 : 6, height:6, borderRadius:3, border:0, cursor:"pointer",
              background: i===idx ? "#7ab3f0" : "rgba(122,179,240,0.3)",
              transition:"width 300ms ease, background 300ms ease", padding:0 }} />
        ))}
      </div>
    </div>
  );
};

const TestimonyBand = () => {
  const sectionRef = useTBRef(null);
  const [cursor, setCursor] = useTBState({ x:-2000, y:-2000, active:false });
  const [reveals, setReveals] = useTBState([0,0,0,0]);
  const zoneRefs = [useTBRef(null), useTBRef(null), useTBRef(null), useTBRef(null)];

  const handleMove = (e) => {
    if (!sectionRef.current) return;
    const sr = sectionRef.current.getBoundingClientRect();
    const cx = e.clientX - sr.left;
    const cy = e.clientY - sr.top;
    setCursor({ x:cx, y:cy, active:true });
    setReveals(zoneRefs.map(ref => {
      if (!ref.current) return 0;
      const r = ref.current.getBoundingClientRect();
      const qcx = r.left + r.width/2 - sr.left;
      const qcy = r.top + r.height/2 - sr.top;
      const dist = Math.hypot(cx - qcx, cy - qcy);
      return Math.max(0, Math.min(1, 1 - (dist - 70) / 180));
    }));
  };

  const handleLeave = () => { setCursor(p => ({ ...p, active:false })); setReveals([0,0,0,0]); };

  const bgGradient = cursor.active
    ? `radial-gradient(480px circle at ${cursor.x}px ${cursor.y}px, rgba(80,100,240,0.16) 0%, rgba(50,70,180,0.06) 45%, transparent 70%), #1a2744`
    : "#1a2744";

  const stats = [
    { n:"40",     suffix:"+", l:"Years preserving memory" },
    { n:"10000",  suffix:"+", l:"Testimonies recorded" },
    { n:"500000", suffix:"+", l:"Students reached" },
    { n:"1000",   suffix:"+", l:"Programs delivered" },
  ];

  return (
    <section ref={sectionRef} onMouseMove={handleMove} onMouseLeave={handleLeave}
      style={{ color:"#fff", padding:"88px 0", position:"relative", overflow:"hidden", cursor:"default",
               background: bgGradient, transition:"background 200ms ease" }}>

      {/* Desktop: absolute positioned faces */}
      <div className="tb-absolute" style={{ position:"absolute", inset:0, pointerEvents:"none", zIndex:1 }}>
        {TESTIMONY_QUOTES.map((q,i) => <WaterFace key={i} ref={zoneRefs[i]} data={q} reveal={reveals[i]} />)}
      </div>

      <Container style={{ position:"relative", zIndex:2, pointerEvents:"none" }}>
        <Reveal>
          <div style={{ maxWidth:720, margin:"0 auto", textAlign:"center", pointerEvents:"auto" }}>
            <Eyebrow onDark>Share your testimony</Eyebrow>
            <blockquote style={{ margin:"0 auto 24px", fontSize:28, fontWeight:700, lineHeight:1.35, color:"#fff", maxWidth:660 }}>
              "For the dead and the living, we must bear witness."
              <div style={{ marginTop:14, fontSize:12, fontWeight:700, letterSpacing:"0.12em", textTransform:"uppercase", color:"#7ab3f0" }}>
                &#x2014; Elie Wiesel
              </div>
            </blockquote>
            <p style={{ fontSize:16, lineHeight:1.7, color:"rgba(255,255,255,0.82)", margin:"0 auto 28px", maxWidth:"58ch" }}>
              If you are a Survivor, Liberator, or Witness &#x2014; or a family member who carries a story forward &#x2014; HDEC will preserve your testimony for generations to come.
            </p>
            <Button variant="primary">Share your testimony</Button>
            <div style={{ marginTop:18, fontSize:11, fontWeight:700, letterSpacing:"0.14em", textTransform:"uppercase", color:"rgba(122,179,240,0.4)" }}>
              Hover the faces &#xb7; hear their voices
            </div>
          </div>
        </Reveal>

        {/* Tablet: 3-col static face grid (below button area) */}
        <div className="tb-grid" style={{ pointerEvents:"auto" }}>
          {TESTIMONY_QUOTES.map((q,i) => <FaceCard key={i} data={q} />)}
        </div>

        {/* Mobile: auto-rotating carousel */}
        <div className="tb-carousel" style={{ pointerEvents:"auto" }}>
          <FaceCarousel />
        </div>

        {/* Stats */}
        <div className="hdec-grid-4" style={{ marginTop:64, borderTop:"1px solid rgba(122,179,240,0.2)", paddingTop:40, pointerEvents:"auto" }}>
          {stats.map((s,i) => (
            <Reveal key={i} delay={i*100}>
              <div style={{ textAlign:"center" }}>
                <div style={{ fontSize:44, fontWeight:700, lineHeight:1, color:"#fff", marginBottom:8, letterSpacing:"-0.01em" }}>
                  <CountUp value={s.n} suffix={s.suffix} duration={1200} startDelay={i*1200} />
                </div>
                <div style={{ fontSize:11, fontWeight:700, letterSpacing:"0.12em", textTransform:"uppercase", color:"#7ab3f0" }}>{s.l}</div>
              </div>
            </Reveal>
          ))}
        </div>
      </Container>
    </section>
  );
};
window.TestimonyBand = TestimonyBand;
  </script>'''

