const Hero = () => {
  const [i, setI] = useHeroState(0);
  const [paused, setPaused] = useHeroState(false);
  const total = HERO_SLIDES.length;
  const goTo = (n) => setI(((n % total) + total) % total);
  useHeroEffect(() => {
    if (paused) return;
    const id = setInterval(() => setI(c => (c + 1) % total), 7000);
    return () => clearInterval(id);
  }, [paused, total]);
  return (
    <section onMouseEnter={() => setPaused(true)} onMouseLeave={() => setPaused(false)}
      style={{ position:"relative",color:"#fff",overflow:"hidden",background:"#1a2744" }}
      aria-roledescription="carousel" aria-label="HDEC highlights" role="region">
      {HERO_SLIDES.map((s,idx) => (
        <div key={idx} aria-hidden={idx!==i} style={{ position:idx===0?"relative":"absolute", inset:idx===0?"auto":0, top:0,left:0,right:0, opacity:idx===i?1:0, transition:"opacity 600ms ease", pointerEvents:idx===i?"auto":"none", minHeight:560, display:"flex",alignItems:"center" }}>
          <img src={s.img} alt={s.alt} style={{ position:"absolute",inset:0,width:"100%",height:"100%",objectFit:"cover" }} />
          <div style={{ position:"absolute",inset:0,background:"rgba(15,22,32,0.72)" }} />
          <Container style={{ position:"relative",padding:"96px 24px",width:"100%" }}>
            <div style={{ maxWidth:720 }}>
              <Eyebrow onDark>{s.eyebrow}</Eyebrow>
              <h1 style={{ fontSize:48,fontWeight:700,lineHeight:1.15,margin:"0 0 18px",color:"#fff",letterSpacing:"-0.005em" }}>{s.title}</h1>
              <p style={{ fontSize:18,lineHeight:1.6,color:"rgba(255,255,255,0.88)",maxWidth:560,margin:"0 0 28px" }}>{s.body}</p>
              <div style={{ display:"flex",gap:12,flexWrap:"wrap" }}>
                <Button variant="primary">{s.cta}</Button>
                <Button variant="ghost">Learn more</Button>
              </div>
            </div>
          </Container>
        </div>
      ))}
      <div style={{ position:"absolute",left:0,right:0,bottom:0,background:"linear-gradient(to top,rgba(15,22,32,0.55),rgba(15,22,32,0))" }}>
        <Container style={{ display:"flex",alignItems:"center",justifyContent:"space-between",padding:"18px 24px" }}>
          <div style={{ display:"flex",gap:28,flex:1,maxWidth:720 }}>
            {HERO_SLIDES.map((s,idx) => (
              <button key={idx} onClick={() => goTo(idx)} style={{ flex:1,textAlign:"left",background:"transparent",border:0,color:"#fff",cursor:"pointer",padding:"10px 0 0",borderTop:idx===i?"3px solid #fff":"3px solid rgba(255,255,255,0.25)",fontFamily:"Arial,sans-serif",transition:"border-color 200ms ease" }} aria-current={idx===i?"true":undefined} aria-label={"Show slide "+(idx+1)}>
                <div style={{ fontSize:10,fontWeight:700,letterSpacing:"0.14em",textTransform:"uppercase",color:idx===i?"#a8d4f5":"rgba(168,212,245,0.7)",marginBottom:4 }}>{String(idx+1).padStart(2,"0")}</div>
                <div style={{ fontSize:13,fontWeight:700,lineHeight:1.35,color:idx===i?"#fff":"rgba(255,255,255,0.7)" }}>{s.eyebrow}</div>
              </button>
            ))}
          </div>
          <div style={{ display:"flex",gap:10,marginLeft:24 }}>
            <button onClick={() => goTo(i-1)} aria-label="Previous slide" style={{ width:40,height:40,borderRadius:4,background:"rgba(255,255,255,0.12)",color:"#fff",border:"1px solid rgba(255,255,255,0.35)",cursor:"pointer",display:"inline-flex",alignItems:"center",justifyContent:"center" }}>
